import zlib

def rec(seq, kind, txid, payload=b''):
    h = len(payload).to_bytes(4,'little') + seq.to_bytes(4,'little') + bytes([kind]) + txid.to_bytes(4,'little')
    return h + payload + (zlib.crc32(h+payload)&0xffffffff).to_bytes(4,'little')

def patch(seq, txid, pidx, boff, data):
    p = pidx.to_bytes(2,'little')+boff.to_bytes(2,'little')+len(data).to_bytes(2,'little')+data
    return rec(seq,2,txid,p)

def commit(seq, txid, payloads):
    body = b''.join(payloads)
    return rec(seq,3,txid, len(payloads).to_bytes(4,'little') + (zlib.crc32(body)&0xffffffff).to_bytes(4,'little'))

def begin(seq,txid): return rec(seq,1,txid,b'')
def abort(seq,txid): return rec(seq,4,txid,b'')
